// n8n Webhook puts the POST payload in `body`; manual tests may provide it directly.
const request = $input.first().json;
const payload = request.body ?? request;

// Discard only events Strapi explicitly identifies as a non-Booking model.
// Some Strapi webhook payloads omit the model field entirely.
const model = String(payload.model ?? payload.contentType ?? '').toLowerCase();
if (model && !['booking', 'bookings', 'api::booking.booking'].includes(model)) {
  return [];
}

const entry = payload.entry?.attributes ?? payload.entry ?? payload.data?.attributes ?? payload.data ?? payload;

// Do not append a misleading row containing only the fallback status.
if (!entry || !entry.customerName || !entry.phone || !entry.email || !entry.date || !entry.time) {
  throw new Error('Booking data was not found in the Strapi webhook body. Check the Webhook node input.');
}

// Google Sheets cells need scalar values. Prefer the relation's display name,
// while keeping the ID as a safe fallback if the webhook was not populated.
const relationValue = (value) => {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string' || typeof value === 'number') return String(value);

  const relation = value.data ?? value;
  const attributes = relation.attributes ?? relation;
  return String(
    attributes.name ??
      attributes.title ??
      attributes.username ??
      attributes.documentId ??
      attributes.id ??
      ''
  );
};

// These property names must exactly match row 1 of the Bookings sheet.
return [
  {
    json: {
      bookingId: String(entry.documentId ?? entry.id ?? ''),
      customerName: String(entry.customerName),
      phone: String(entry.phone),
      email: String(entry.email),
      date: String(entry.date),
      time: String(entry.time),
      service: relationValue(entry.service),
      staff: relationValue(entry.staff),
      status: String(entry.status ?? 'pending')
    }
  }
];

// A Slack approval resumes this execution with data.approved.
// Retrieve the original booking data so its documentId is never taken from Slack.
const booking = $items('Extract Booking Details', 0, 0)[0].json;
const approved = $json.data?.approved;

if (typeof approved !== 'boolean') {
  throw new Error('Slack did not return an approval decision.');
}

return [
  {
    json: {
      ...booking,
      status: approved ? 'confirmed' : 'cancelled',
      decidedBy: $json.data?.responder?.name ?? $json.data?.responder?.id ?? 'Slack approver'
    }
  }
];
